#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
enum Priority {
    #[default]
    Low,
    Medium,
    High,
}

#[derive(Debug, Clone, PartialEq, Default)]
struct Task {
    title: String,
    priority: Priority,
    done: bool,
}

fn main() {
    let mut ps = vec![Priority::High, Priority::Low, Priority::Medium];
    ps.sort();
    println!("{ps:?}");
    println!("{}", Priority::High > Priority::Medium);

    let t = Task { title: String::from("write tests"), ..Default::default() };
    let copy = t.clone();
    println!("{t:?}");
    println!("{}", t == copy);
}

use std::fmt;

struct Money {
    cents: i64,
}

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let sign = if self.cents < 0 { "-" } else { "" };
        let c = self.cents.abs();
        write!(f, "{sign}${}.{:02}", c / 100, c % 100)
    }
}

fn main() {
    let price = Money { cents: 1999 };
    println!("{price}");
    println!("{}", Money { cents: -5 });
    let s: String = price.to_string();
    println!("{} characters", s.len());
}

